with filtered as (select *, substring(email, 1, 3) as email_prefix, regexp_replace(email, ' ', '-') as email_slug from employees where hire_date >= to_date('2023-11-20') and job_title is not null) select case when salary >= 150000 then 'HIGH' else 'LOW' end as salary_tier, date_trunc('month', hire_date) as activity_month, percentile_approx(salary, array(0.25, 0.5, 0.75)) as salary_quartiles, count(distinct manager_id) as distinct_manager_ids, round(avg(salary), 2) as avg_salary, avg(salary) as avg_salary_2 from filtered group by salary_tier, activity_month order by salary_tier desc
